package com.project7.localmanager;
import java.io.*;import java.util.*;
/** Reuses original dynamic reducers/granters for composable first-acquisition families. */
final class WishMechanism {
 static final String KEY="q7WishMechanism";
 static DynamicTransition.State read(MultiWishSpec spec,byte[]state)throws Exception{byte[]d=BsonLite.documentValue(state,KEY);WishCatalog.need(!BsonLite.keys(state).contains(KEY)||d!=null,"mechanism type");int ct=WishChoosePolicy.value(state,"ct",0),points=pair(state,"jzc",spec.target);List<Integer>receipts=new ArrayList<>();if(d!=null){WishCatalog.need(WishCatalog.SHA256.equals(BsonLite.stringValue(d,"hash"))&&Integer.valueOf(spec.epoch).equals(BsonLite.intValue(d,"epoch"))&&MultiWishState.POLICY.equals(BsonLite.stringValue(d,"policy"))&&Integer.valueOf(ct).equals(BsonLite.intValue(d,"draws")),"mechanism scope/count");points=WishChoosePolicy.value(d,"points",-1);receipts=BsonLite.intArrayValues(d,"receipts");WishCatalog.need(receipts!=null,"mechanism receipts");}else for(DynamicTransition.Threshold t:spec.rules.jiaozhi)if(t.at<=points)receipts.add(t.id);
  Set<Integer>valid=new HashSet<>();for(DynamicTransition.Threshold t:spec.rules.jiaozhi){valid.add(t.id);WishCatalog.need(receipts.contains(t.id)==(t.at<=points),"mechanism receipt threshold");}WishCatalog.need(valid.containsAll(receipts),"mechanism receipt identity");return new DynamicTransition.State(ct,points,Collections.<Integer>emptyList(),receipts,Collections.<Integer>emptyList());}
 static int pair(byte[]state,String key,int target)throws Exception{byte[]a=BsonLite.arrayValue(state,key);int n=0;boolean found=false;if(a!=null)for(byte[]p:LocalResourceEngine.array(a))if(Integer.valueOf(target).equals(BsonLite.intValue(p,"0"))){WishCatalog.need(!found,"target pair duplicate");found=true;n=WishChoosePolicy.value(p,"1",-1);WishCatalog.need(n>=0,"target pair value");}return n;}
 static byte[]save(byte[]state,MultiWishSpec spec,DynamicTransition.State s)throws Exception{byte[]old=BsonLite.documentValue(state,KEY);if(old==null)old=BsonLite.EMPTY_DOCUMENT;old=BsonLite.withProfileString(old,"hash",WishCatalog.SHA256);old=BsonLite.withProfileInt(old,"epoch",spec.epoch);old=BsonLite.withProfileString(old,"policy",MultiWishState.POLICY);old=BsonLite.withProfileInt(old,"draws",s.draws);old=BsonLite.withProfileInt(old,"points",s.points);old=BsonLite.withProfileArray(old,"receipts",new ArrayList<>(s.jiaozhiReceipts));state=BsonLite.withProfileDocument(state,KEY,old);if(spec.target>0)state=WishChoosePolicy.pair(state,"jzc",spec.target,s.points);return state;}
 static byte[]grantRandom(LocalResourceEngine.Result result,LocalResourceCatalog catalog,int rr,Random random)throws Exception{DynamicCatalog c=DynamicDrawPolicy.ready();Map<?,?>r=DynamicCatalog.map(c.random.get(rr));int point=random.nextInt(DynamicCatalog.num(r.get("total")));for(Object o:DynamicCatalog.list(r.get("positive_edges"))){List<?>p=DynamicCatalog.list(o);point-=DynamicCatalog.num(p.get(1));if(point<0)return DynamicDrawPolicy.grantSupplement(result,catalog,DynamicCatalog.num(p.get(0)));}throw new AssertionError();}
 static byte[]jiaozhi(LocalResourceEngine.Result result,LocalResourceCatalog catalog,MultiWishSpec spec,DynamicTransition.State before,HistoryCatalog.Leaf primary,Random random)throws Exception{DynamicTransition.Step step=DynamicTransition.primary(spec.rules,before,primary.id,primary.kind.equals("hero"),primary.kind.equals("memory"));WishCatalog.need(step.grants.isEmpty(),"unexpected charge source");DynamicTransition.Step grants=DynamicTransition.settle(spec.rules,step.state);byte[]bonus=BsonLite.document("item",Collections.emptyList(),"hero",Collections.emptyList(),"treasure",Collections.emptyList());for(DynamicTransition.Threshold t:grants.grants)for(int rid:t.rewards()){byte[]b=grantRandom(result,catalog,rid,random);WishCatalog.need(HistoryBson.required(HistoryBson.parse(b),"hero").values().isEmpty(),"recursive jiaozhi hero");for(String k:Arrays.asList("item","treasure"))bonus=WishDrawPolicy.append(bonus,k,b);}byte[]state=LocalDrawEngine.state(result.profile,spec.pool);state=save(state,spec,grants.state);LocalDrawEngine.saveState(result,state,spec.pool);return bonus;}
}
